def _web(t) -> dict[str, Any]:
    i, lang, raw, what, who, action, pages, style, ftext, facts, must = t
    brief = (f"{raw}\n\nWHAT IT IS: {what}.\nWHO VISITS: {who}.\nTHE ONE KEY ACTION: {action}.\nPAGES: {', '.join(pages)}.\n"
             f"STYLE: {style}.\nFACTS (use exactly, invent nothing else): {ftext}.\n"
             "MUST NOT: invent prices, phone numbers, reviews or awards; leave a marked blank where a fact is missing.")
    return {"id": i, "section": "web", "lang": lang, "raw": raw, "brief": brief, "facts": facts, "must": must,
            "slots": {"what": what, "who": who, "action": action, "pages": pages, "style": style, "facts": ftext}}


def _image(t) -> dict[str, Any]:
    i, lang, raw, subject, scene, comp, style, light, words, script, aspect, colours, must = t
    brief = (f"{style[0].upper() + style[1:]} of {subject}, {scene}. Composition: {comp}. Light: {light}. "
             f"Colours: {colours}. ")
    brief += (f'The exact words "{words}" are written on the picture in {script} letters, large and clearly readable, '
              "spelled exactly as given; no other text." if words else "No text, letters or logo anywhere in the picture.")
    return {"id": i, "section": "image", "lang": lang, "raw": raw, "brief": brief, "aspect": aspect, "words": words,
            "facts": [], "must": must,
            "slots": {"subject": subject, "scene": scene, "composition": comp, "style": style, "light": light,
                      "words": words, "colours": colours, "size": aspect}}


def _script(t) -> dict[str, Any]:
    i, lang, raw, fmt, secs, aud, hook, msg, proof, facts, cta, tone, language, must = t
    brief = (f"{raw}\n\nPLATFORM: {fmt}, {secs} seconds.\nAUDIENCE: {aud}.\nOPENING HOOK (first 3 seconds): {hook}.\n"
             f"THE ONE MESSAGE: {msg}.\nFACTS (say exactly, invent no other price, number or claim): {proof}.\n"
             f"CALL TO ACTION (the last line): {cta}.\nTONE: {tone}.")
    return {"id": i, "section": "script", "lang": lang, "raw": raw, "brief": brief, "facts": facts, "must": must,
            "fmt": fmt, "secs": secs, "language": language, "tone": tone,
            "slots": {"platform": fmt, "length": secs, "audience": aud, "hook": hook, "message": msg, "proof": proof,
                      "cta": cta, "tone": tone}}


ASKS: list[dict[str, Any]] = [*map(_web, _WEB), *map(_image, _IMAGE), *map(_script, _SCRIPT)]
